mapper.select:
select
mn.*
from Pro_Year_Cons_Plan mn

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.State=#{params.state}
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and mn.Ycp_Start_Time>=#{params.ycpStartTimeStart}
    
    
        and mn.Ycp_Start_Time<=#{params.ycpStartTimeEnd}
    
    
        and mn.Ycp_End_Time>=#{params.ycpEndTimeStart}
    
    
        and mn.Ycp_End_Time<=#{params.ycpEndTimeEnd}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
